WITH r AS (SELECT * FROM bestiary_mobs FINAL WHERE zone_id = {zone:Int64} AND mob_name = {name:String} AND capture_id NOT IN (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged')), m AS (SELECT model, sumMapIfMerge(moves) AS mv, sumMapIfMerge(shapes_out) AS o, groupArraySortedMapIfMerge(1)(shape_proofs) AS p, groupArraySortedMapIfMerge(2)(range_uses) AS ru, sumMapIfMerge(range_missed) AS rm FROM r GROUP BY model) SELECT toString(model) AS name, id, uses, [o.2[indexOf(o.1, id)], o.3[indexOf(o.1, id)], o.4[indexOf(o.1, id)], o.5[indexOf(o.1, id)]] AS shapes_out, arrayMap(k -> if(empty(p[id * 4 + k]), NULL, p[id * 4 + k][1]), [0, 1, 2, 3]) AS proofs, arrayMap(k -> ru[id * 2 + k], [0, 1]) AS reach, arrayMap(k -> arrayMap(i -> [rm.1[i].2, toFloat64(rm.2[i])], arrayFilter(i -> rm.1[i].1 = id * 2 + k, arrayEnumerate(rm.1))), [0, 1]) AS missed FROM m ARRAY JOIN mv.1 AS id, mv.2 AS uses WHERE uses > 0 ORDER BY name, id
